mapper.select:
SELECT asset.*, COALESCE( ( SELECT department.dept_name FROM sys_user usage_user LEFT JOIN sys_department department ON department.id = usage_user.primary_department_id AND department.deleted_at = 0 WHERE usage_user.id = asset.assignee_id AND usage_user.deleted_at = 0 ), '' ) AS assignee_department_name,
CASE WHEN asset.asset_type = 'PIXEL' THEN ( SELECT GROUP_CONCAT( DISTINCT CONCAT( assignment.user_name, COALESCE( CONCAT(' · ', department.dept_name), '' ) ) ORDER BY assignment.assigned_at SEPARATOR '、' ) FROM media_asset_user_assignment assignment LEFT JOIN sys_user usage_user ON usage_user.id = assignment.user_id AND usage_user.deleted_at = 0 LEFT JOIN sys_department department ON department.id = usage_user.primary_department_id AND department.deleted_at = 0 WHERE assignment.asset_id = asset.id AND assignment.deleted_at = 0 ) WHEN asset.asset_type = 'AD_ACCOUNT' THEN ( SELECT COALESCE( NULLIF( ( SELECT channel_account.operator_name FROM media_channel_account channel_account WHERE channel_account.account_id = asset.asset_code AND channel_account.deleted_at = 0 LIMIT 1 ), '' ), ( SELECT GROUP_CONCAT( DISTINCT assignment.assignee_name ORDER BY assignment.assigned_at SEPARATOR '、' ) FROM media_channel_account_assignment assignment LEFT JOIN sys_user usage_user ON usage_user.id = assignment.assignee_id AND usage_user.deleted_at = 0 LEFT JOIN sys_department department ON department.id = usage_user.primary_department_id AND department.deleted_at = 0 WHERE assignment.account_id = asset.asset_code AND assignment.deleted_at = 0 ) ) ) END AS usage_user_names, CASE WHEN asset.asset_type = 'PIXEL' THEN ( SELECT GROUP_CONCAT(DISTINCT assignment.user_id ORDER BY assignment.assigned_at SEPARATOR ',') FROM media_asset_user_assignment assignment WHERE assignment.asset_id = asset.id AND assignment.deleted_at = 0 ) WHEN asset.asset_type = 'AD_ACCOUNT' THEN ( SELECT GROUP_CONCAT(DISTINCT assignment.assignee_id ORDER BY assignment.assigned_at SEPARATOR ',') FROM media_channel_account_assignment assignment WHERE assignment.account_id = asset.asset_code AND assignment.deleted_at = 0 ) END AS usage_user_ids , CASE WHEN asset.asset_type = 'PIXEL' THEN ( SELECT GROUP_CONCAT( DISTINCT department.dept_name ORDER BY assignment.assigned_at SEPARATOR '、' ) FROM media_asset_user_assignment assignment LEFT JOIN sys_user usage_user ON usage_user.id = assignment.user_id AND usage_user.deleted_at = 0 LEFT JOIN sys_department department ON department.id = usage_user.primary_department_id AND department.deleted_at = 0 WHERE assignment.asset_id = asset.id AND assignment.deleted_at = 0 ) WHEN asset.asset_type = 'AD_ACCOUNT' THEN ( SELECT GROUP_CONCAT( DISTINCT department.dept_name ORDER BY assignment.assigned_at SEPARATOR '、' ) FROM media_channel_account_assignment assignment LEFT JOIN sys_user usage_user ON usage_user.id = assignment.assignee_id AND usage_user.deleted_at = 0 LEFT JOIN sys_department department ON department.id = usage_user.primary_department_id AND department.deleted_at = 0 WHERE assignment.account_id = asset.asset_code AND assignment.deleted_at = 0 ) END AS usage_department_names FROM media_asset asset WHERE asset.deleted_at = 0 AND asset.asset_type = #{assetType}
AND ( asset.assignee_id = #{assigneeId} OR EXISTS ( SELECT 1 FROM media_channel_account_assignment assignment WHERE assignment.account_id = asset.asset_code AND assignment.assignee_id = #{assigneeId} AND assignment.deleted_at = 0 ) OR EXISTS ( SELECT 1 FROM media_asset_user_assignment assignment WHERE asset.asset_type IN ('PIXEL', 'AD_ACCOUNT') AND assignment.asset_id = asset.id AND assignment.user_id = #{assigneeId} AND assignment.deleted_at = 0 ) )
AND COALESCE(asset.channel_id, asset.project_id) = #{channelId}
ORDER BY asset.created_at DESC, asset.id DESC

SELECT *
FROM media_asset
WHERE asset_type = #{assetType}
  AND asset_code = #{assetCode}
  AND deleted_at = 0

SELECT * FROM media_asset WHERE asset_type = #{assetType} AND asset_code IN
#{assetCode}
AND deleted_at = 0 ORDER BY id

