INSERT INTO media_asset (
    asset_type, asset_name, asset_code, project_id, project_name,
    channel_id, channel_name, secret_data, status, application_id,
    assignee_id, assignee_name, usage_team, remark, created_by, updated_by
) VALUES (
    #{assetType}, #{assetName}, #{assetCode}, #{projectId}, #{projectName},
    #{channelId}, #{channelName}, #{secretData}, #{status}, #{applicationId},
    #{assigneeId}, #{assigneeName}, #{usageTeam}, #{remark}, #{createdBy}, #{updatedBy}
)

INSERT INTO media_asset_import_log (
    asset_subtype, file_name, total_count, success_count, failure_count,
    failure_details, failed_file_ciphertext, operator_id
) VALUES (
    #{assetSubtype}, #{fileName}, #{totalCount}, #{successCount}, #{failureCount},
    #{failureDetails}, #{failedFileCiphertext}, #{operatorId}
)

mapper.select:
SELECT id, asset_subtype, file_name, total_count, success_count, failure_count,
       failure_details, operator_id, created_at
FROM media_asset_import_log
WHERE operator_id = #{operatorId}
ORDER BY created_at DESC, id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM media_asset_import_log
WHERE operator_id = #{operatorId}

SELECT id, asset_subtype, file_name, total_count, success_count, failure_count,
       failure_details, failed_file_ciphertext, operator_id, created_at
FROM media_asset_import_log
WHERE id = #{id}
  AND operator_id = #{operatorId}

SELECT id
FROM sys_user
WHERE status = 1
  AND deleted_at = 0
  AND (
      username = #{name}
      OR display_name = #{name}
      OR real_name = #{name}
  )

SELECT COUNT(*)
FROM pm_project
WHERE id = #{projectId}
  AND project_name = #{projectName}
  AND deleted_at = 0

