UPDATE media_asset_user_assignment
SET deleted_at = #{deletedAt}, updated_at = CURRENT_TIMESTAMP(3), assigned_by = #{operatorId}
WHERE asset_id = #{assetId} AND deleted_at = 0

UPDATE media_asset_user_assignment
SET deleted_at = #{deletedAt}, updated_at = CURRENT_TIMESTAMP(3), assigned_by = #{operatorId}
WHERE user_id = #{userId} AND deleted_at = 0

UPDATE media_approval_config
SET deleted_at=#{deletedAt}, updated_by=#{operatorId}
WHERE id=#{id} AND deleted_at=0

